import{_ as a,o as l,c as t,a3 as r}from"./chunks/framework.D1iekJsc.js";const h=JSON.parse('{"title":"Install llama.cpp","description":"Use llama.cpp / llama-server with GGUF to expose an OpenAI-compatible API for MiniTavern.","frontmatter":{"title":"Install llama.cpp","description":"Use llama.cpp / llama-server with GGUF to expose an OpenAI-compatible API for MiniTavern.","head":[["meta",{"name":"keywords","content":"tavern,AI tavern,MiniTavern,AI companion,AI friend,AI local chat,Silly Tavern,SillyTavern,Silly Tavern mobile,Silly Tavern Android,Silly Tavern iOS,AI roleplay,character card,AI chat,mobile AI,offline AI,AI story,local LLM,Ollama,LM Studio,lorebook,regex,BYOK,user guide,docs,AI chat client"}],["meta",{"property":"og:title","content":"Install llama.cpp · MiniTavern Docs"}],["meta",{"property":"og:description","content":"Use llama.cpp / llama-server with GGUF to expose an OpenAI-compatible API for MiniTavern."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/en/llamacpp/install"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/en/llamacpp/install"}]]},"headers":[],"relativePath":"en/llamacpp/install.md","filePath":"en/llamacpp/install.md","lastUpdated":1787224147000}'),n={name:"en/llamacpp/install.md"};function o(i,e,s,c,p,d){return l(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="install-and-get-started-llama-cpp" tabindex="-1">Install and get started (llama.cpp) <a class="header-anchor" href="#install-and-get-started-llama-cpp" aria-label="Permalink to &quot;Install and get started (llama.cpp)&quot;">​</a></h1><p><a href="https://github.com/ggerganov/llama.cpp" target="_blank" rel="noreferrer">llama.cpp</a> provides high-performance GGUF inference; <strong><code>llama-server</code></strong> (or the server binary in your release) can expose an HTTP API for MiniTavern.</p><p>Best for: users who already download GGUF and want few dependencies and controllable flags. If you only want click-to-download, start with <a href="/ultra_guides/en/lmstudio/install">LM Studio</a> or <a href="/ultra_guides/en/ollama/install">Ollama</a>.</p><h2 id="get-it" tabindex="-1">Get it <a class="header-anchor" href="#get-it" aria-label="Permalink to &quot;Get it&quot;">​</a></h2><ol><li>Download a prebuilt package from official Releases, or compile per docs (CUDA / Metal / Vulkan).</li><li>Confirm a <strong>server</strong> executable is present (<code>llama-server</code>, <code>server</code>, etc. — follow your build).</li><li>Prepare a GGUF model — see <a href="/ultra_guides/en/local/models">Recommended models</a>.</li></ol><h2 id="quick-check" tabindex="-1">Quick check <a class="header-anchor" href="#quick-check" aria-label="Permalink to &quot;Quick check&quot;">​</a></h2><p>Once the model runs locally, enable the HTTP service (next page). First make sure CLI load has no errors.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><p><a href="./server">Start server</a> → <a href="/ultra_guides/en/connect-app/minitavern">Configure in MiniTavern</a></p>',9)])])}const u=a(n,[["render",o]]);export{h as __pageData,u as default};
